"""The `retailer_txn` parser (D3 §5.5, §13). Every file is generated by `make_sources` or edited from its output."""

import json
from datetime import date, datetime

import pytest

from energatron.adapters.sources.retailer_txn import RETAILER_TXN, RetailerTxnParser
from energatron.core.errors import InvalidInputError
from energatron.core.models.catalog import Coverage, SourceInfo, SourceType
from energatron.ports.sources import SourceParser
from tests.fixtures.make_sources import make_retailer_txn_csv

NAME = "transactions_all.csv"
RENAMED = "export.csv"
INVOICE = "Invoice - Synthetic invoice SYNINV0001"
ENTRIES = (
    ("Payment - Synthetic payment", datetime(2025, 2, 3), "-1.00"),
    (INVOICE, datetime(2025, 3, 4, 10, 0, 0), "1.00"),
    ("Adjustment - Synthetic adjustment", datetime(2025, 1, 2), "0"),
)


def txn(entries: tuple[tuple[str, datetime, str], ...] = ENTRIES) -> bytes:
    return make_retailer_txn_csv(entries)


def inspect(data: bytes, filename: str = NAME) -> SourceInfo:
    return RETAILER_TXN.inspect(filename, data)


def reason(data: bytes) -> str:
    with pytest.raises(InvalidInputError) as caught:
        inspect(data)
    value = caught.value.details["reason"]
    assert isinstance(value, str)
    return value


def edit(data: bytes, old: str, new: str) -> bytes:
    text = data.decode("utf-8")
    assert old in text
    return text.replace(old, new, 1).encode("utf-8")


def test_the_parser_is_a_source_parser_for_retailer_txn_version_1() -> None:
    parser: SourceParser = RETAILER_TXN
    assert isinstance(RETAILER_TXN, RetailerTxnParser)
    assert parser.source is SourceType.RETAILER_TXN and parser.version == 1


def test_detect() -> None:
    both = RETAILER_TXN.detect("Transactions_All.CSV", txn())
    assert both is not None and both.evidence == ("filename", "content")
    content = RETAILER_TXN.detect(RENAMED, txn())
    assert content is not None and content.evidence == ("content",)
    filename = RETAILER_TXN.detect(NAME, b"Description,Date\r\n")
    assert filename is not None and filename.evidence == ("filename",)
    assert RETAILER_TXN.detect(RENAMED, b"Description,Date,Amount,Extra\r\n") is None
    assert RETAILER_TXN.detect(RENAMED, b"description,date,amount\r\n") is None


def test_detect_drops_a_bom_takes_lf_and_needs_only_the_head() -> None:
    detection = RETAILER_TXN.detect(RENAMED, b"\xef\xbb\xbf" + txn().replace(b"\r\n", b"\n"))
    assert detection is not None and detection.evidence == ("content",)
    data = txn(ENTRIES * 800)
    assert len(data) > 64 * 1024
    head = RETAILER_TXN.detect(NAME, data[: 64 * 1024])
    assert head is not None and head.evidence == ("filename", "content")


def test_inspect_an_export() -> None:
    info = inspect(txn())
    assert info.source_ts == datetime(2025, 3, 4, 10, 0, 0)
    assert info.coverage == Coverage(start=date(2025, 1, 2), end=date(2025, 3, 4))
    assert info.extra == {"rows": 3, "source_ts_from": "content"}
    assert info.identifiers == {}
    assert info.extension == ".csv"


def test_description_text_never_reaches_extra() -> None:
    assert "SYNINV0001" not in json.dumps(inspect(txn()).extra)


def test_a_quoted_description_with_a_comma_is_one_field() -> None:
    entries = (('"Payment - Synthetic, with a comma"', datetime(2025, 1, 1), "1.00"),)
    assert inspect(txn(entries)).extra["rows"] == 1


@pytest.mark.parametrize(
    ("old", "new", "expected"),
    [
        (",-1.00\r", ",-1.00,x\r", "bad_field_count"),
        (",2025-02-03T00:00:00,", ",03/02/2025,", "bad_datetime"),
        (",-1.00\r", ",minus one\r", "bad_number"),
        (",-1.00\r", ",\r", "bad_number"),
    ],
)
def test_malformed(old: str, new: str, expected: str) -> None:
    assert reason(edit(txn(), old, new)) == expected


def test_a_header_alone_has_no_data_and_another_header_is_bad() -> None:
    assert reason(txn(())) == "no_data"
    assert reason(b"Description,When,Amount\r\nx,2025-01-01T00:00:00,1\r\n") == "bad_header"


def test_an_error_never_holds_description_text() -> None:
    with pytest.raises(InvalidInputError) as caught:
        inspect(edit(txn(), ",1.00\r", ",1.00,x\r"))
    assert "SYNINV0001" not in json.dumps({"message": caught.value.message, **caught.value.details})


def test_inspect_drops_a_bom_and_takes_lf() -> None:
    assert inspect(b"\xef\xbb\xbf" + txn().replace(b"\r\n", b"\n")).extra["rows"] == 3
